import{_ as i,a0 as r,w as u,s as d,ao as n,I as s,x as e,a1 as p,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"文檔寫作的 DevOps 指南 | LCTT x X-CMD","titleTemplate":false,"description":"文檔寫作的 DevOps 指南 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"文檔寫作的 DevOps 指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"文檔寫作的 DevOps 指南 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20210330 A DevOps guide to documentation","title":"文檔寫作的 DevOps 指南","tag":"202212","desc":""},"relativePath":"202212/20210330 A DevOps guide to documentation.md","filePath":"[post].md"}'),a={name:"202212/20210330 A DevOps guide to documentation.md"};function D(v,t,m,f,O,T){const o=r("Link");return u(),d("div",null,[t[41]||(t[41]=n('<h1 id="文檔寫作的-devops-指南" tabindex="-1">文檔寫作的 DevOps 指南 <a class="header-anchor" href="#文檔寫作的-devops-指南" aria-label="Permalink to “文檔寫作的 DevOps 指南”">​</a></h1><blockquote><p>將文檔寫作加入到 DevOps 的生命週期中。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202212/15/101537c4kcxxzqzh6fxkor.jpg" alt=""></p><p>DevOps 正在挑戰技術文檔的規範，這在 IT 歷史上是前所未有的。從自動化到提高交付速度，再到拆除瀑布式軟件開發生命週期模型，這意味着業務和技術文檔寫作的理念需要做出巨大改變。</p><p>以下是 DevOps 對技術文檔寫作不同方面的影響。</p><h3 id="技術寫手的角色變化" tabindex="-1">技術寫手的角色變化 <a class="header-anchor" href="#技術寫手的角色變化" aria-label="Permalink to “技術寫手的角色變化”">​</a></h3><p>技術寫手必須適應 DevOps。好消息是，許多技術寫手已經加入到開發團隊中，並且擁有合作關係和不斷增長的產品知識的技術寫手很具優勢。</p><p>但是如果一個技術寫手習慣於獨立工作，並依賴於領域專家的草稿作為文檔的基礎，那麼就需要做一些調整。</p>',8)),s("p",null,[t[2]||(t[2]=e("進行一些投資，以確保文檔和其他與項目有關的內容開發工作獲得所需的工具、結構和支持。從改變 ",-1)),p(o,{href:"https://opensource.com/article/19/11/hiring-technical-writers-devops"},{default:l(()=>[...t[0]||(t[0]=[e("技術寫手聘用方式",-1)])]),_:1}),t[3]||(t[3]=e(" 開始。以 ",-1)),p(o,{href:"https://searchitoperations.techtarget.com/opinion/Make-DevOps-documentation-an-integral-part-of-your-strategy?_ga=2.73253915.980148481.1610758264-908287796.1564772842"},{default:l(()=>[...t[1]||(t[1]=[e("DevOps 的速度",-1)])]),_:1}),t[4]||(t[4]=e(" 編寫文檔需要重新思考內容規劃，並打破 DevOps 團隊和支持項目的技術寫手之間長期存在的隔閡。",-1))]),s("p",null,[t[6]||(t[6]=e("DevOps 使開發團隊擺脱了傳統文檔實踐的束縛。首先，文檔 ",-1)),p(o,{href:"https://www.agilealliance.org/glossary/definition-of-done"},{default:l(()=>[...t[5]||(t[5]=[e("完成的定義",-1)])]),_:1}),t[7]||(t[7]=e(" 必須改變。一些企業的文化使技術寫手成為軟件開發的被動參與者。DevOps 提出了新的要求：隨着 DevOps 文化的轉變，技術寫手的角色也應發生變化。技術寫手需要（且必須適應）DevOps 提供的透明度。他們必須融入 DevOps 團隊。取決於組織如何塑造這個角色，將技術寫手帶入團隊可能會帶來技能上的挑戰。",-1))]),t[42]||(t[42]=s("h3",{id:"文檔標準、方法和規格",tabindex:"-1"},[e("文檔標準、方法和規格 "),s("a",{class:"header-anchor",href:"#文檔標準、方法和規格","aria-label":"Permalink to “文檔標準、方法和規格”"},"​")],-1)),t[43]||(t[43]=s("p",null,"雖然 DevOps 還沒有影響到技術文檔本身，但開源社區已經加強了對應用編程接口（API）文檔的幫助，已經有不同規模的企業的 DevOps 團隊正在使用這些文檔。",-1)),s("p",null,[t[9]||(t[9]=e("用於記錄 API 的開源規範和工具是個非常值得關注的領域。我想這是由於 ",-1)),p(o,{href:"https://developers.google.com/season-of-docs"},{default:l(()=>[...t[8]||(t[8]=[e("谷歌文檔季",-1)])]),_:1}),t[10]||(t[10]=e(" 的影響，它使開源軟件項目能夠獲得專業的技術寫作人才來解決他們最關鍵的文檔項目。",-1))]),s("p",null,[t[12]||(t[12]=e("開源 API 屬於 DevOps 文檔討論的一部分。雲原生應用集成需求的重要性正在上升。",-1)),p(o,{href:"https://swagger.io/specification/"},{default:l(()=>[...t[11]||(t[11]=[e("OpenAPI 規範",-1)])]),_:1}),t[13]||(t[13]=e("（一個定義和記錄 API 的開放標準）是在 DevOps 環境下 API 文檔的良好資源。然而，該規範會導致文檔的創建和更新過程變得很費時，這使其飽受批評。",-1))]),s("p",null,[t[17]||(t[17]=e("曾經也有短暫嘗試過創建 ",-1)),s("ruby",null,[p(o,{href:"https://devops.com/continuous-documentation"},{default:l(()=>[...t[14]||(t[14]=[e("持續文檔",-1)])]),_:1}),t[15]||(t[15]=s("rt",null,"Continuous Documentation",-1))]),t[18]||(t[18]=e("，並且還有一個來自 CA（現在的 Broadcom）的創建 ",-1)),p(o,{href:"https://www.cmswire.com/cms/information-management/the-importance-of-docops-in-the-new-era-of-business-027489.php"},{default:l(()=>[...t[16]||(t[16]=[e("DocOps",-1)])]),_:1}),t[19]||(t[19]=e(" 框架的運動。然而，DocOps 從來沒有作為一個行業運動流行起來。",-1))]),t[44]||(t[44]=s("p",null,"DevOps 文檔標準的現狀意味着 DevOps 團隊（包括技術寫手）需要在項目的最初階段就開始創建文檔。要做到這一點，你需要把文檔作為一個敏捷故事和（同樣重要的）管理期望，並且把它與年度績效評估放在一起執行。",-1)),t[45]||(t[45]=s("h3",{id:"文檔工具",tabindex:"-1"},[e("文檔工具 "),s("a",{class:"header-anchor",href:"#文檔工具","aria-label":"Permalink to “文檔工具”"},"​")],-1)),s("p",null,[t[21]||(t[21]=e("文檔的編寫應該以一種所有團隊成員都可以使用的格式或平台在線進行。MediaWiki、DokuWiki、TikiWiki 和其他 ",-1)),p(o,{href:"https://opensource.com/article/20/7/sharepoint-alternative"},{default:l(()=>[...t[20]||(t[20]=[e("開源維基",-1)])]),_:1}),t[22]||(t[22]=e(" 為 DevOps 團隊提供了一個編寫和維護文檔的中央倉庫。",-1))]),t[46]||(t[46]=s("p",null,"讓團隊選擇他們的維基平台，就像讓他們選擇他們的其他持續集成/持續開發（CI/CD）工具鏈一樣。開源維基強大之處在於其可擴展性。例如，DokuWiki 包括一系列的擴展，你可以通過安裝這些擴展來創建一個符合你的 DevOps 團隊的創作要求的平台。",-1)),s("p",null,[t[24]||(t[24]=e("如果你有足夠的野心來加強你的團隊的編寫和協作能力，",-1)),p(o,{href:"https://opensource.com/article/20/7/nextcloud"},{default:l(()=>[...t[23]||(t[23]=[e("Nextcloud",-1)])]),_:1}),t[25]||(t[25]=e("（一個開源的雲協作套件）是一個讓你的 DevOps 團隊上網並給他們提供編寫文檔所需工具的選擇。",-1))]),t[47]||(t[47]=n('<h3 id="devops-最佳實踐" tabindex="-1">DevOps 最佳實踐 <a class="header-anchor" href="#devops-最佳實踐" aria-label="Permalink to “DevOps 最佳實踐”">​</a></h3><p>文檔在 DevOps 轉型中也發揮着作用。例如，你會想要記錄組織從 DevOps 實現效率和流程增益的最佳實踐，這些信息太重要了，不能靠着 DevOps 團中之間口耳相傳。如果你所在的組織有多個 DevOps 團隊，那麼文檔就是統一的力量，它可以促進最佳實踐的標準化，並設置了衡量代碼質量的基準指標。</p><p>一般情況下，開發人員承擔了記錄 DevOps 實踐的工作。即使他們的組織有技術寫手，他們也可能跨開發團隊工作。因此，開發人員和系統管理員能夠捕捉、記錄和交流他們的最佳實踐是很重要的。這裏有一些朝正確的方向發展的提示：</p><ul><li>提前花時間為 DevOps 最佳實踐創建標準模板。不要陷入複製在線模板的陷阱。採訪利益相關者和團隊來創建一個符合團隊需求的模板。</li><li>尋找一些創造性的信息收集的方法，例如記錄團隊會議和使用聊天系統日誌來作為文檔的基礎。</li><li>建立一個用於發佈最佳實踐的維基。使用維基可以跟蹤編輯和更新。這樣的平台可以幫助團隊在最佳實踐發生變化時進行更新和維護。</li></ul><p>當在構建 CI/CD 工具鏈時記錄依賴關係是非常明智的。尤其是當加入新的團隊成員時，你會發現這些記錄非常有用，另外當團隊成員忘記一些事情時，這也是一種保險。</p><p>最後，自動化對 DevOps 利益相關者和從業者都很有吸引力。在自動化中斷之前，一切都很有趣。擁有自動化運行手冊、管理指南和其他內容的文檔（並且是最新的）意味着無論何時發生故障，員工都可以讓自動化重新工作。</p><h3 id="最後一些想法" tabindex="-1">最後一些想法 <a class="header-anchor" href="#最後一些想法" aria-label="Permalink to “最後一些想法”">​</a></h3><p>DevOps 對於技術文檔來説是一個積極的因素。它將內容開發納入 DevOps 生命週期，並打破組織文化中開發人員和技術作者之間的隔閡。在沒有技術寫手的情況下，團隊就可以使用工具來加快文檔創作的速度，以與 DevOps 的速度相匹配。</p><p>你的組織將如何把文檔加入到 DevOps 生命週期？請在評論區分享你的經驗。</p><hr>',10)),s("p",null,[t[27]||(t[27]=e("via: ",-1)),p(o,{href:"https://opensource.com/article/21/3/devops-documentation"},{default:l(()=>[...t[26]||(t[26]=[e("https://opensource.com/article/21/3/devops-documentation",-1)])]),_:1})]),s("p",null,[t[32]||(t[32]=e("作者：",-1)),p(o,{href:"https://opensource.com/users/willkelly"},{default:l(()=>[...t[28]||(t[28]=[e("Will Kelly",-1)])]),_:1}),t[33]||(t[33]=e(" 選題：",-1)),p(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[29]||(t[29]=[e("lujun9972",-1)])]),_:1}),t[34]||(t[34]=e(" 譯者：",-1)),p(o,{href:"https://github.com/Veryzzj"},{default:l(()=>[...t[30]||(t[30]=[e("Veryzzj",-1)])]),_:1}),t[35]||(t[35]=e(" 校對：",-1)),p(o,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:l(()=>[...t[31]||(t[31]=[e("校對者ID",-1)])]),_:1})]),s("p",null,[t[38]||(t[38]=e("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[36]||(t[36]=[e("LCTT",-1)])]),_:1}),t[39]||(t[39]=e(" 原創編譯，",-1)),p(o,{href:"https://linux.cn/"},{default:l(()=>[...t[37]||(t[37]=[e("Linux中國",-1)])]),_:1}),t[40]||(t[40]=e(" 榮譽推出",-1))])])}const x=i(a,[["render",D]]);export{k as __pageData,x as default};
